# Monospaced typewriter simulator (public-domain concept)
PICA = 10  # chars per inch
MARGIN = 65

class Typewriter:
    def __init__(self, width=MARGIN):
        self.width, self.line, self.page = width, [], []
    def type(self, text):
        for ch in text:
            if ch == "\n" or len(self.line) >= self.width:
                self.carriage_return()
                if ch == "\n": continue
            if ch == "\b":  # backspace + X overstrike = correction era
                if self.line: self.line.pop()
                continue
            self.line.append(ch)
    def carriage_return(self):
        self.page.append("".join(self.line)); self.line = []
        print("*ding*  carriage returned")
    def show(self):
        self.carriage_return()
        print("+" + "-" * self.width + "+")
        for ln in self.page:
            print("|" + ln.ljust(self.width) + "|")
        print("+" + "-" * self.width + "+")

tw = Typewriter(40)
tw.type("THE QUICK BROWN FOX\nJUMPS OVER THE LAZY DOG")
tw.show()
print(f"pitch: {PICA} chars/inch -> 40-char line = {40/PICA} inches wide")
